// Two-tier route preview scheduling.
//
// `GET /api/v1/routing/explain` answers in two very different times: with
// `fast=true` it runs the heuristic classifier only — no local-model call, no
// sockets, ~6-8 ms of daemon work — while the full call is 0.14-0.22 s warm and
// up to ~1.5 s when the local classifier is cold. A preview that only ever made
// the full call either lagged the typist or blanked on every keystroke.
//
// So: every keystroke schedules a *quick estimate* (fast), and a pause schedules
// the *answer* (full) that replaces it. The quick estimate is labelled as one;
// the label drops when the full answer lands. Neither is ever the decision —
// Enter engages, and the daemon routes again at run time.
//
// This module is pure: no DOM, no `vscode`, no fetch. The host supplies one
// `fetch(tier, …)` and gets state callbacks back, which is what makes the whole
// sequencing testable with fake timers. It compiles under the extension host's
// DOM-less lib and the webview's DOM lib alike.
//
// MIRRORED FILE — the byte-identical twin lives at
// `apps/nexus-desktop/src/bridge/previewScheduler.ts`, and
// `apps/forge-ide/test/previewScheduler.test.ts` fails if the two drift.
// Edit one, copy it to the other.

/** Which of the two explain calls produced a value. */
export type PreviewTier = "fast" | "full";

/**
 * `--dur-1` from glass-ui.md §4.7. Long enough that a fast typist sends one
 * fast call per burst rather than one per character; short enough that the
 * quick estimate reads as instant next to a ~16 ms round trip.
 */
export const FAST_DEBOUNCE_MS = 120;

/** Stillness after the last keystroke before the full call is worth its latency. */
export const SETTLE_MS = 900;

/** Below this a directive cannot be classified usefully — don't ask. */
export const PREVIEW_MIN_CHARS = 4;

/** Per-tier bound on the session cache. */
export const PREVIEW_CACHE_MAX = 40;

/**
 * Fast and full results are cached under separate keys on purpose: they are
 * different answers to the same question, and a fast hit must never be served
 * where the full answer is what the caller asked for.
 */
export function previewCacheKey(tier: PreviewTier, scope: string, directive: string): string {
  return `${tier}␟${scope}␟${directive}`;
}

export interface PreviewState<T> {
  /** The trimmed directive this state describes; "" when idle. */
  directive: string;
  /** Caller-defined cache scope — the project id, in both bars. */
  scope: string;
  /** Last answer worth showing. Kept on screen across keystrokes rather than blanked. */
  value: T | null;
  /** Which call produced `value`. `"fast"` is what the UI labels a quick estimate. */
  tier: PreviewTier | null;
  /** A call is in flight. */
  loading: boolean;
  loadingTier: PreviewTier | null;
  /** Set only when nothing is on screen for this directive and the last attempt failed. */
  error: string | null;
  /**
   * The full answer just replaced a quick estimate that said something else —
   * a local second opinion raised the risk, say. The UI animates the change
   * instead of swapping it silently.
   */
  changed: boolean;
  /** Increments with every `changed` emission, so a UI can key an animation off it. */
  changeToken: number;
}

export interface PreviewSchedulerOptions<T> {
  /**
   * Ask the daemon. Rejecting is fine; an abort must reject or never settle.
   * Returning `null` means "the daemon declined to answer" and is surfaced as
   * an error, not as an empty preview.
   */
  fetch(tier: PreviewTier, directive: string, scope: string, signal: AbortSignal): Promise<T | null>;
  /** Called on every state transition, including back to idle. */
  onChange(state: PreviewState<T>): void;
  /**
   * What counts as "the same answer". Only a difference here animates. Default
   * is reference equality, which for freshly parsed JSON means "always differs" —
   * both bars pass a real fingerprint.
   */
  fingerprint?(value: T): string;
  fastDebounceMs?: number;
  settleMs?: number;
  minChars?: number;
  cacheMax?: number;
}

function idle<T>(changeToken: number): PreviewState<T> {
  return {
    directive: "",
    scope: "",
    value: null,
    tier: null,
    loading: false,
    loadingTier: null,
    error: null,
    changed: false,
    changeToken,
  };
}

/**
 * Drives the fast → full sequence for one input field.
 *
 * Ordering rules, all of which exist to stop the strip flickering:
 *  - every keystroke supersedes the previous one (generation bump + abort);
 *  - a reply whose generation is stale is dropped, never rendered;
 *  - a fast reply that arrives *after* the full answer for the same generation
 *    is dropped — the cheaper answer never overwrites the better one;
 *  - a failed full call leaves a landed quick estimate on screen rather than
 *    replacing a usable preview with an error.
 */
export class PreviewScheduler<T> {
  private readonly options: Required<Omit<PreviewSchedulerOptions<T>, "fingerprint">> &
    Pick<PreviewSchedulerOptions<T>, "fingerprint">;

  private readonly fastCache = new Map<string, T>();
  private readonly fullCache = new Map<string, T>();

  /** Bumped by every input change and by reset; stale replies are dropped against it. */
  private generation = 0;
  /** Generation whose full answer has already landed. */
  private fullLandedGeneration = -1;
  private fastTimer: ReturnType<typeof setTimeout> | undefined;
  private settleTimer: ReturnType<typeof setTimeout> | undefined;
  private fastAbort: AbortController | undefined;
  private fullAbort: AbortController | undefined;
  private fullInFlight = false;
  private changeToken = 0;
  private current: PreviewState<T>;
  private disposed = false;

  constructor(options: PreviewSchedulerOptions<T>) {
    this.options = {
      fastDebounceMs: FAST_DEBOUNCE_MS,
      settleMs: SETTLE_MS,
      minChars: PREVIEW_MIN_CHARS,
      cacheMax: PREVIEW_CACHE_MAX,
      ...options,
    };
    this.current = idle<T>(0);
  }

  get state(): PreviewState<T> {
    return this.current;
  }

  /** Test/introspection hook: how many answers of each tier are held. */
  cacheSize(tier: PreviewTier): number {
    return (tier === "fast" ? this.fastCache : this.fullCache).size;
  }

  /**
   * A keystroke. Idempotent for an unchanged directive+scope, so cursor moves
   * and re-renders do not re-arm the timers or re-ask the daemon.
   */
  input(directive: string, scope = ""): void {
    if (this.disposed) return;
    const trimmed = directive.trim();
    if (trimmed === this.current.directive && scope === this.current.scope) return;
    if (trimmed.length < this.options.minChars && this.current.directive === "") {
      // Already idle and still too short — nothing to cancel, nothing to emit.
      return;
    }

    this.cancelPending();
    const generation = ++this.generation;

    if (trimmed.length < this.options.minChars) {
      this.emit(idle<T>(this.changeToken));
      return;
    }

    // A cached full answer is the real answer: serve it and ask nothing at all.
    const full = this.fullCache.get(previewCacheKey("full", scope, trimmed));
    if (full !== undefined) {
      this.fullLandedGeneration = generation;
      this.emit({
        directive: trimmed,
        scope,
        value: full,
        tier: "full",
        loading: false,
        loadingTier: null,
        error: null,
        changed: false,
        changeToken: this.changeToken,
      });
      return;
    }

    // A cached quick estimate saves the fast call but not the full one: the
    // whole point of the pause is to replace the estimate with the answer.
    const fast = this.fastCache.get(previewCacheKey("fast", scope, trimmed));
    if (fast !== undefined) {
      this.emit({
        directive: trimmed,
        scope,
        value: fast,
        tier: "fast",
        loading: false,
        loadingTier: null,
        error: null,
        changed: false,
        changeToken: this.changeToken,
      });
    } else {
      // Keep the previous answer visible while the next one is fetched. A strip
      // that blanks on every keystroke reads as broken rather than as busy.
      this.emit({
        directive: trimmed,
        scope,
        value: this.current.value,
        tier: this.current.tier,
        loading: true,
        loadingTier: "fast",
        error: null,
        changed: false,
        changeToken: this.changeToken,
      });
      this.fastTimer = setTimeout(() => {
        this.fastTimer = undefined;
        void this.run("fast", generation, trimmed, scope);
      }, this.options.fastDebounceMs);
    }

    this.settleTimer = setTimeout(() => {
      this.settleTimer = undefined;
      void this.run("full", generation, trimmed, scope);
    }, this.options.settleMs);
  }

  /**
   * The user stopped caring about waiting — focus left the field. Fires the full
   * call now instead of at the end of the settle window. A fast call already in
   * flight is left alone: it may still paint first, and the ordering rules stop
   * it overwriting the full answer.
   */
  settle(): void {
    if (this.disposed) return;
    if (this.settleTimer !== undefined) {
      clearTimeout(this.settleTimer);
      this.settleTimer = undefined;
    }
    const { directive, scope } = this.current;
    if (directive.length < this.options.minChars) return;
    if (this.fullInFlight || this.fullLandedGeneration === this.generation) return;
    void this.run("full", this.generation, directive, scope);
  }

  /** Directive engaged or field cleared: drop everything on screen and in flight. */
  reset(): void {
    if (this.disposed) return;
    this.cancelPending();
    this.generation++;
    this.emit(idle<T>(this.changeToken));
  }

  dispose(): void {
    this.cancelPending();
    this.disposed = true;
  }

  // --- internals -----------------------------------------------------------

  private cancelPending(): void {
    if (this.fastTimer !== undefined) clearTimeout(this.fastTimer);
    if (this.settleTimer !== undefined) clearTimeout(this.settleTimer);
    this.fastTimer = undefined;
    this.settleTimer = undefined;
    this.fastAbort?.abort();
    this.fullAbort?.abort();
    this.fastAbort = undefined;
    this.fullAbort = undefined;
    this.fullInFlight = false;
  }

  private async run(tier: PreviewTier, generation: number, directive: string, scope: string): Promise<void> {
    if (this.disposed || generation !== this.generation) return;
    // Nothing to gain from a fast call once the full answer for this text is in.
    if (tier === "fast" && this.fullLandedGeneration === generation) return;

    const controller = new AbortController();
    if (tier === "fast") {
      this.fastAbort = controller;
    } else {
      this.fullAbort = controller;
      this.fullInFlight = true;
    }

    // Only show the spinner for a tier the user is actually waiting on: the
    // full call running behind a rendered quick estimate is not a wait.
    if (tier === "full" && this.current.value === null && generation === this.generation) {
      this.emit({ ...this.current, loading: true, loadingTier: "full" });
    }

    let value: T | null = null;
    let failure: string | null = null;
    try {
      value = await this.options.fetch(tier, directive, scope, controller.signal);
    } catch (cause) {
      failure = cause instanceof Error ? cause.message : String(cause);
    }

    if (tier === "full") this.fullInFlight = false;

    if (this.disposed || controller.signal.aborted || generation !== this.generation) return;
    // The full answer landed while this fast call was in the air. Drop it.
    if (tier === "fast" && this.fullLandedGeneration === generation) return;

    if (value === null) {
      this.fail(tier, failure ?? "The council did not answer.", generation);
      return;
    }

    this.remember(tier, scope, directive, value);
    if (tier === "full") this.fullLandedGeneration = generation;

    const previous = this.current;
    const differs =
      tier === "full" &&
      previous.tier === "fast" &&
      previous.value !== null &&
      this.fingerprint(previous.value) !== this.fingerprint(value);
    if (differs) this.changeToken++;

    this.emit({
      directive,
      scope,
      value,
      tier,
      loading: tier === "fast" && this.fullPendingFor(generation),
      loadingTier: tier === "fast" && this.fullPendingFor(generation) ? "full" : null,
      error: null,
      changed: differs,
      changeToken: this.changeToken,
    });
  }

  private fullPendingFor(generation: number): boolean {
    return (
      generation === this.generation &&
      this.fullLandedGeneration !== generation &&
      (this.fullInFlight || this.settleTimer !== undefined)
    );
  }

  /**
   * A failed call must not take a usable preview off the screen. The error only
   * surfaces when there is nothing better to show for this directive.
   */
  private fail(tier: PreviewTier, message: string, generation: number): void {
    if (this.current.value !== null) {
      const waiting = tier === "fast" && this.fullPendingFor(generation);
      this.emit({
        ...this.current,
        loading: waiting,
        loadingTier: waiting ? "full" : null,
        changed: false,
      });
      return;
    }
    this.emit({
      ...this.current,
      value: null,
      tier: null,
      loading: false,
      loadingTier: null,
      error: message,
      changed: false,
    });
  }

  private fingerprint(value: T): string {
    const fn = this.options.fingerprint;
    return fn === undefined ? JSON.stringify(value) : fn(value);
  }

  private remember(tier: PreviewTier, scope: string, directive: string, value: T): void {
    const cache = tier === "fast" ? this.fastCache : this.fullCache;
    if (cache.size >= this.options.cacheMax) {
      const oldest = cache.keys().next();
      if (oldest.done !== true) cache.delete(oldest.value);
    }
    cache.set(previewCacheKey(tier, scope, directive), value);
  }

  private emit(next: PreviewState<T>): void {
    this.current = next;
    this.options.onChange(next);
  }
}
